float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdBox( vec3 p, vec3 b ) {
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

mat2 rot2D(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

// cubic polynomial
float smin( float a, float b, float k ) {
    float h = max( k-abs(a-b), 0.0 )/k;
    return min(a,b) - h*h*h*k*(1.0/6.0);
}

float sdOctahedron( vec3 p, float s ) {
  p = abs(p);
  float m = p.x+p.y+p.z-s;
  vec3 q;
       if( 3.0*p.x < m ) q = p.xyz;
  else if( 3.0*p.y < m ) q = p.yzx;
  else if( 3.0*p.z < m ) q = p.zxy;
  else return m*0.57735027;

  float k = clamp(0.5*(q.z-q.y+s),0.0,s); 
  return length(vec3(q.x,q.y-s+k,q.z-k)); 
}

float map(vec3 p) {
    //vec3 spherePos = vec3(sin(iTime)*3., 0, 0);
    //float sphere = sdSphere(p - spherePos, 1.); // Sphere SDF

    //vec3 q = p; // Input point copy

    p.z += iTime * .4; // Upward movement

    //q = fract(q) - .5; // Space repetition
    p.xy = (fract(p.xy) - .5);
    p.z = mod(p.z, .25) - .125;

    float box = sdOctahedron(p, .15); // Box SDF

    //float ground = p.y + .75;

    //return smin(ground, smin(sphere, box, 2.), 1.);
    return box;
}

vec3 palette( in float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

    return a + b*cos( 6.283185*(c*t+d) );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2. - iResolution.xy) / iResolution.y;
    vec2 m = (iMouse.xy * 2. - iResolution.xy) / iResolution.y;

    // Initialization
    vec3 ro = vec3(0, 0, -3); // ray origin
    vec3 rd = normalize(vec3(uv, 1)); // ray direction
    vec3 col = vec3(0);

    float t = 0.; // total distance travelled

    // Horizontal camera rotation
    // ro.yz *= rot2D(-m.y);
    // rd.yz *= rot2D(-m.y);

    // Horizontal camera rotation
    // ro.xz *= rot2D(-m.x);
    // rd.xz *= rot2D(-m.x);

    // 

    if (iMouse.z < 0.) m = vec2(cos(iTime*.2), sin(iTime*.2));

    //Raymarching
    int i;
    for(i = 0; i < 80; i++) {
        vec3 p = ro + rd * t; // position along the ray

        p.xy *= rot2D(t*.2 * m.x); // rotate around z-axis

        p.y += sin(t*(m.y+1.))*.35; // wiggle ray

        float d = map(p); // curent distance to the scene

        t += d; // "march" the ray

        if (d < .001 || t > 100.) break; // early stop
    }

    // Coloring
    //col = vec3(t * .05); // color based on distance
    col = palette(t*.04 + float(i)*.005);

    fragColor = vec4(col, 1);
}
